def lempel_ziv_complexity(seq):
    seq = tuple(seq)
    if not seq:
        return 0
    c, i, n = 1, 1, len(seq)
    while i < n:
        found = False
        for l in range(1, n - i + 1):
            sub = seq[i:i + l]
            if sub not in [seq[j:j + l] for j in range(max(0, i - l), i)]:
                found = True
                i += l
                c += 1
                break
        if not found:
            c += 1
            break
    return c
